import os
from pathlib import Path

import pytest


def first_readable(names: list[str]) -> str:
    """Return the text of the first readable file named in `names`.

    Each name is a relative path (subdirectories allowed, e.g. "sub/b.txt")
    resolved inside the directory `notes` in the current working directory.
    Names are untrusted: any name that would reach a file outside `notes`
    (via "..", absolute paths, symlinks, NUL bytes, etc.) is treated as
    unreadable and skipped. Missing, unreadable, or non-file entries are
    skipped too. Returns "" when no name yields a readable file.
    """
    try:
        base = Path("notes").resolve()
    except (OSError, RuntimeError, ValueError):
        return ""
    for name in names:
        if "\x00" in name:
            continue
        try:
            candidate = (base / name).resolve()
            if not candidate.is_relative_to(base):
                continue
            if not candidate.is_file():
                continue
            return candidate.read_text(encoding="utf-8")
        except (OSError, RuntimeError, ValueError):
            continue
    return ""


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("A")
    (notes / "sub" / "b.txt").write_text("B")
    (tmp_path / "secret.txt").write_text("SECRET")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_first_file(root: Path) -> None:
    assert first_readable(["a.txt"]) == "A"


def test_first_of_several(root: Path) -> None:
    assert first_readable(["a.txt", "sub/b.txt"]) == "A"


def test_subdirectory(root: Path) -> None:
    assert first_readable(["sub/b.txt"]) == "B"


def test_skips_missing(root: Path) -> None:
    assert first_readable(["nope.txt", "sub/nope.txt", "sub/b.txt"]) == "B"


def test_none_readable(root: Path) -> None:
    assert first_readable(["nope.txt", "also/nope.txt"]) == ""


def test_empty_list(root: Path) -> None:
    assert first_readable([]) == ""


def test_empty_file_counts_as_readable(root: Path) -> None:
    (root / "notes" / "empty.txt").write_text("")
    assert first_readable(["empty.txt", "a.txt"]) == ""


def test_notes_directory_missing(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    assert first_readable(["a.txt"]) == ""


def test_directory_names_skipped(root: Path) -> None:
    assert first_readable(["sub", "", ".", "a.txt"]) == "A"


def test_parent_traversal_blocked(root: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt"]) == ""
    assert first_readable(["notes/../../secret.txt"]) == ""
    assert first_readable(["../notes/../secret.txt"]) == ""
    assert first_readable(["..//secret.txt"]) == ""


def test_traversal_skipped_then_valid_name_used(root: Path) -> None:
    assert first_readable(["../secret.txt", "sub/b.txt"]) == "B"


def test_absolute_path_outside_blocked(root: Path) -> None:
    assert first_readable([str(root / "secret.txt")]) == ""
    assert first_readable(["/etc/passwd"]) == ""


def test_absolute_path_style_name_does_not_escape(root: Path) -> None:
    # A leading slash must never resolve to the filesystem root.
    assert first_readable(["/secret.txt"]) == ""


def test_nul_byte_name(root: Path) -> None:
    assert first_readable(["a.txt\x00../../secret.txt", "a\x00.txt", "a.txt"]) == "A"


def test_symlink_file_escaping_blocked(root: Path) -> None:
    link = root / "notes" / "link.txt"
    try:
        link.symlink_to(root / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert first_readable(["link.txt"]) == ""
    assert first_readable(["link.txt", "a.txt"]) == "A"


def test_symlink_dir_escaping_blocked(root: Path) -> None:
    outside = root / "outside"
    outside.mkdir()
    (outside / "x.txt").write_text("X")
    link = root / "notes" / "dirlink"
    try:
        link.symlink_to(outside, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert first_readable(["dirlink/x.txt"]) == ""
    assert first_readable(["dirlink/../secret.txt"]) == ""


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="permission bits not enforced for root / unsupported",
)
def test_unreadable_file_skipped(root: Path) -> None:
    locked = root / "notes" / "locked.txt"
    locked.write_text("L")
    locked.chmod(0)
    try:
        assert first_readable(["locked.txt", "a.txt"]) == "A"
        assert first_readable(["locked.txt"]) == ""
    finally:
        locked.chmod(0o600)

